/**
 * Lifetime totals the in-game Lifetime panel does not list: kills, damage and coins split by
 * source, kills by enemy type, and every currency's lifetime flow.
 *
 * Each entry is the save's own lifetime counter, read as stored. Nothing here is derived.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LIFETIME_BREAKDOWN_SAVE_KEY_BY_STAT, readLifetimeBreakdownFromSaveRoot
 * depends    src/save/access/values, src/save/lifetime/types
 * used by    src/save/lifetime/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import { coerceSaveNumber } from '../access/values'
import type { LifetimeBreakdownSaveExtract } from './types'

/** Save keys behind each total, as a v29.2 official export names them. */
export const LIFETIME_BREAKDOWN_SAVE_KEY_BY_STAT = {
  killsBySource: {
    orbs: ['totalEnemiesDestroyedByOrbs', 'totalEnemiesDestryoedByOrbs'],
    deathRay: 'totalEnemiesDestroyedByDeathRay',
    thorns: 'totalEnemiesDestroyedByThorn',
    droppedLandMines: 'totalEnemiesDestroyedByDroppedLandMines',
    projectiles: 'totalEnemiesDestroyedByProjectiles',
    chainLightning: 'totalEnemiesDestroyedByChainLightning',
    smartMissiles: 'totalEnemiesDestroyedBySmartMissiles',
    innerLandMines: 'totalEnemiesDestroyedByInnerLandMines',
    poisonSwamp: 'totalEnemiesDestroyedByPoisonSwamp',
    blackHole: 'totalEnemiesDestroyedByBlackHole',
    flameBot: 'totalEnemiesDestroyedByFlameBot',
    deathPenalty: 'totalEnemiesDestroyedByDeathPenalty',
    other: 'totalEnemiesDestroyedByOther',
  },
  killsByEnemyType: {
    basic: 'totalEnemiesDestroyedNormal',
    fast: 'totalEnemiesDestroyedFast',
    tank: 'totalEnemiesDestroyedTank',
    ranged: 'totalEnemiesDestroyedRanged',
    boss: 'totalEnemiesDestroyedBoss',
    protector: 'totalEnemiesDestroyedProtector',
  },
  damageBySource: {
    thorns: 'totalDamageByThorn',
    smartMissiles: 'totalDamageBySmartMissiles',
    landMines: 'totalDamageByLandMines',
    droppedLandMines: 'totalDamageByDroppedLandMines',
    deathWave: 'totalDamageByDeathWave',
    chainLightning: 'totalDamageByChainLightning',
    poisonSwamp: 'totalDamageBySwamp',
    blackHole: 'totalDamageByBlackHole',
    guardian: 'totalDamageByGuardian',
    bots: 'totalDamageByBot',
  },
  coinsBySource: {
    kills: 'totalCoinsEarnedFromKills',
    waves: 'totalCoinsEarnedFromWaves',
    adBonus: 'totalCoinsEarnedFromAdBonus',
    mine: 'totalCoinsEarnedFromMine',
    blackHole: 'blackHoleCoins',
    spotlight: 'spotlightCoins',
    bots: 'totalCoinsByBot',
    guardian: 'totalCoinsByGuardian',
  },
  other: {
    droppedLandMinesSpawned: 'totalDroppedLandMinesSpawned',
    deathDefies: 'totalDeathDefyCount',
    lifestealAbsorbed: 'totalLifestealAbsorbed',
    botStuns: 'totalStunsByBot',
    guardianCatches: 'totalCatchesByGuardian',
    playTimeSeconds: 'playTime',
  },
} as const

/** `[earned, spent, bought]` keys per currency; null where the game keeps no such counter. */
const CURRENCY_FLOW_SAVE_KEYS: Record<string, readonly [string | null, string | null, string | null]> = {
  gems: ['totalGemsEarned', null, 'totalGemsBought'],
  stones: ['totalStonesEarned', 'totalStonesSpent', 'totalStonesBought'],
  medals: ['totalMedalsEarned', 'totalMedalsSpent', null],
  cells: ['totalCellsEarned_v2', 'totalCellsSpent_v2', null],
  keys: ['totalKeysEarned', 'totalKeysSpent', null],
  tokens: ['totalTokensEarned', 'totalTokensSpent', null],
  bits: ['totalBitsEarned', 'totalBitsSpent', null],
}

function read(root: Record<string, unknown>, key: string | readonly string[] | null): number | null {
  if (key === null) return null
  if (typeof key === 'string') return coerceSaveNumber(root[key])
  for (const spelling of key) {
    const value = coerceSaveNumber(root[spelling])
    if (value !== null) return value
  }
  return null
}

function readGroup(root: Record<string, unknown>, group: Record<string, string | readonly string[]>): Record<string, number | null> {
  return Object.fromEntries(Object.entries(group).map(([name, key]) => [name, read(root, key)]))
}

/** Lifetime breakdowns, or null for a save with none of these counters. */
export function readLifetimeBreakdownFromSaveRoot(root: Record<string, unknown> | null): LifetimeBreakdownSaveExtract | null {
  if (!root) return null
  const keys = LIFETIME_BREAKDOWN_SAVE_KEY_BY_STAT
  const extract: LifetimeBreakdownSaveExtract = {
    killsBySource: readGroup(root, keys.killsBySource),
    killsByEnemyType: readGroup(root, keys.killsByEnemyType),
    damageBySource: readGroup(root, keys.damageBySource),
    coinsBySource: readGroup(root, keys.coinsBySource),
    currencies: Object.fromEntries(Object.entries(CURRENCY_FLOW_SAVE_KEYS).map(([name, [earned, spent, bought]]) => [
      name,
      { earned: read(root, earned), spent: read(root, spent), bought: read(root, bought) },
    ])),
    other: readGroup(root, keys.other),
  }
  const anyValue = [extract.killsBySource, extract.killsByEnemyType, extract.damageBySource, extract.coinsBySource, extract.other]
    .some(group => Object.values(group).some(value => value !== null))
  return anyValue ? extract : null
}
